#!/bin/sh
set -eu
cd "$(dirname "$0")/../.."
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
cc -std=c11 -Wall -Wextra -Werror -g -fsanitize=address,undefined -Ikrnl krnl/host-tests/linux_idle_dispatch.c krnl/linux_idle_pit.c krnl/linux_i8042_absent.c krnl/linux_int3.c krnl/linux_msr_gp.c krnl/linux_misc_features.c krnl/linux_feature_control.c krnl/linux_port80.c krnl/linux_nonpresent_pf.c krnl/linux_profile_activation.c krnl/linux_profile_gate.c krnl/linux_cpu_profile.c krnl/linux_acpi_reduced_install.c krnl/linux_acpi_reduced.c krnl/linux_acpi_topology.c krnl/linux_ioapic_mmio.c krnl/linux_apic_dispatch.c krnl/linux_apic_mmio.c krnl/linux_apic_msr.c krnl/linux_mmio_memory.c krnl/linux_guest_irq_glue.c krnl/linux_guest_irq_adapter.c krnl/linux_irq_glue.c krnl/linux_irq_adapter.c krnl/linux_pit2.c krnl/linux_disabled_apic.c krnl/linux_invlpg.c krnl/linux_sysenter_msr.c krnl/linux_debug_disabled.c krnl/linux_pic_mask.c krnl/linux_pause.c krnl/linux_rtc.c krnl/linux_guest_snapshot.c krnl/linux_microcode_model.c krnl/linux_cpu_commit.c krnl/linux_vcpu_policy.c krnl/linux_vcpu_cr.c krnl/linux_gs_commit.c krnl/linux_vcpu_msr.c krnl/linux_efer_commit.c krnl/linux_msr_bank.c krnl/linux_vcpu_state.c krnl/linux_pf_guard_v5.c krnl/linux_vcpu_event.c krnl/linux_high_pf.c krnl/linux_high_pf_data.c krnl/linux_pt_diag.c krnl/linux_pt_permissions.c krnl/linux_uart_runtime.c krnl/linux_uart_model_io.c krnl/linux_uart.c krnl/legacy_irq_runtime.c krnl/guest_wait.c krnl/linux_external_irq.c krnl/pic0_glue.c krnl/pit0_transaction.c krnl/pit0.c krnl/pic0.c krnl/pic0_ports.c krnl/linux_guest_dispatch.c krnl/guest_apic.c krnl/lapic.c krnl/lapic_timer.c krnl/guest_mmio_mov.c krnl/ioapic.c -o "$tmp/test"
ASAN_OPTIONS=detect_leaks=0 "$tmp/test"
for f in krnl/linux_idle_pit.c krnl/linux_guest_dispatch.c; do cc -std=c11 -Wall -Wextra -Werror -ffreestanding -Ikrnl -c "$f" -o "$tmp/$(basename "$f").o"; done
